import 'package:flutter/material.dart';
import 'package:model_viewer_plus/model_viewer_plus.dart';

import 'three_d_support.dart';

/// The split geode (assets/models/geode_crystal.glb, generated by
/// geode/tools/make_geode_crystal_glb.py) in an orbitable model viewer. The WebView
/// exists only while this widget is mounted, and never in flat mode, where
/// [fallback] stands in.
class GeodeCrystalViewer extends StatelessWidget {
  const GeodeCrystalViewer({super.key, required this.fallback, this.height = 260});
  final Widget fallback;
  final double height;

  @override
  Widget build(BuildContext context) {
    final mode = threeDModeIn(context);
    if (mode == ThreeDMode.flat) return fallback;
    return SizedBox(height: height, child: ModelViewer(
      src: 'assets/models/geode_crystal.glb',
      alt: 'A split geode lined with amethyst and jade quartz. Drag to turn it.',
      backgroundColor: Colors.transparent,
      loading: Loading.eager,
      ar: false,
      cameraControls: true,
      // Zoom would capture the page's scroll gesture.
      disableZoom: true,
      disablePan: true,
      autoRotate: mode == ThreeDMode.live,
      rotationPerSecond: '18deg',
      interactionPrompt: InteractionPrompt.none,
      exposure: 1.1,
      shadowIntensity: .6,
      cameraOrbit: '35deg 70deg 105%',
      debugLogging: false,
    ));
  }
}
